import { ChevronDown, Mail, Phone } from 'lucide-react';
import {Suspense, useState} from 'react';
import {Await, NavLink} from 'react-router';

/**
 * @param {FooterProps}
 */
export function Footer({footer: footerPromise, header, publicStoreDomain, collections}) {
  return (
    <Suspense>
      <Await resolve={footerPromise}>
        {(footer) => (
          <footer className="footer">
            {footer?.menu && header.shop.primaryDomain?.url && (
              <FooterMenu
                menu={footer.menu}
                primaryDomainUrl={header.shop.primaryDomain.url}
                publicStoreDomain={publicStoreDomain}
              />
            )}
          </footer>
        )}
      </Await>
    </Suspense>
  );
}

function PagesSection({ title, items }) {
  const [openDrop, setOpenDrop] = useState(false);

  return (
    <div className="w-full lg:hidden border-gray-300">
      {/* Toggle Button */}
      <button
        onClick={() => setOpenDrop(!openDrop)}
        className="w-full flex justify-between items-center py-2 text-sm font-bold text-white"
      >
        {title}
        <ChevronDown
          className={`w-4 h-4 ml-2 transition-transform duration-300 ${
            openDrop ? "rotate-180" : ""
          }`}
        />
      </button>

      {/* Dropdown List with transition */}
      <div
        className={`overflow-hidden transition-all duration-500 ease-in-out ${
          openDrop ? "max-h-96 opacity-100 mt-2" : "max-h-0 opacity-0"
        }`}
      >
        <div className="w-full rounded-md shadow-lg">
          {items.map((col, index) => (
            <NavLink
              to={`/collections/${col.handle}`}
              key={index}
              onClick={() => setOpenDrop(false)}
              className="block w-full py-1 text-sm font-medium hover:text-gray-300"
            >
              {col.title}
            </NavLink>
          ))}
        </div>
      </div>
      <div className='w-full h-[0.5px] mt-4 bg-slate-900'></div>
    </div>
  );
}

export default PagesSection;

